        id: "HEARSAY-TOSS",
        category: "evidential.hearsay-toss",
        family: "quotative-core",
        gloss_ja: "\u4F1D\u805E\u653E\u308A(\u3063\u3066)",
        gloss_en: "hearsay-toss",
        cognitive_effect: "\u300C\u301C\u3093\u3060\u3063\u3066\uFF0F\u306A\u3093\u3060\u3063\u3066\u300D\u4ED6\u8005\u306E\u8A00\u3092\u5F15\u7528\u3057\u305F\u307E\u307E\u8074\u304D\u624B\u306B\u653E\u308A\u8A55\u4FA1\u3092\u59D4\u306D\u308B",
