function highlightInto(el, text, terms) {
  const needles = terms.filter(Boolean);
  if (needles.length === 0) {
    el.appendText(text);
    return;
  }
  const lc = text.toLowerCase();
  const ranges = [];
  for (const term of [...needles].sort((a, b) => b.length - a.length)) {
    const needle = term.toLowerCase();
    let i = 0;
    while ((i = lc.indexOf(needle, i)) !== -1) {
      ranges.push([i, i + term.length]);
      i += term.length;
    }
  }
  if (ranges.length === 0) {
    el.appendText(text);
    return;
  }
  ranges.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const merged = [];
  for (const r2 of ranges) {
    const last = merged[merged.length - 1];
    if (last && r2[0] <= last[1])
      last[1] = Math.max(last[1], r2[1]);
    else
      merged.push([r2[0], r2[1]]);
  }
  let pos = 0;
  for (const [s, e] of merged) {
    if (s > pos)
      el.appendText(text.slice(pos, s));
    el.createSpan({ text: text.slice(s, e), cls: "jp-x-hl" });
    pos = e;
  }
  if (pos < text.length)
    el.appendText(text.slice(pos));
}
